<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElButton,ElInput,ElMessage,ElTag } from 'element-plus'
import { dateText,money,STATUS_LABEL,useCommerceStore } from '@/stores/commerce'
const c=useCommerceStore(),r=useRouter(),route=useRoute();const order=computed(()=>c.data.orders.find(x=>x.id===route.params.id));const tab=ref(String(route.query.tab||'bill'));const files=ref<string[]>([]),note=ref('');const panes=[['bill','订单账单'],['contract','合同'],['delivery','交付'],['settlement','结算与评价'],['service','服务详情']]
function pick(e:Event,kind:'contract'|'delivery'){const list=Array.from((e.target as HTMLInputElement).files||[]);const valid=list.filter(f=>['application/pdf','image/png','image/jpeg','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document'].includes(f.type));if(valid.length!==list.length)ElMessage.error('仅支持 PDF、图片、Word 文件');if(kind==='contract'){if(valid[0]&&order.value)c.submitContract(order.value.id,valid[0].name)}else files.value=valid.map(f=>f.name)}
function deliver(){if(!order.value)return;if(c.requestAcceptance(order.value.id,files.value,note.value)){ElMessage.success('已提交客户验收');files.value=[];note.value=''}else ElMessage.warning('请上传交付文件，确认订单处于可提交状态')}
const refund=computed(()=>order.value?c.activeRefund(order.value.id):undefined);const fromAfterSale=computed(()=>route.query.from==='aftersale');function back(){r.push(fromAfterSale.value?{path:'/aftersale',query:{order:route.params.id}}:'/order')}
</script><template><div class="biz-page" v-if="order"><header class="biz-head"><div><p class="biz-eyebrow"><a @click="back()">{{fromAfterSale?'← 返回售后管理':'订单管理'}}</a> / 订单详情</p><h1>{{STATUS_LABEL[order.status]}}</h1><p>订单号 {{order.id}} · 下单时间 {{dateText(order.createdAt)}}</p></div><ElTag :type="order.status==='completed'?'success':order.status==='cancelled'?'info':'primary'">{{STATUS_LABEL[order.status]}}</ElTag></header><div class="order-layout"><div><div v-if="refund" class="biz-note warn">订单存在进行中退款，合同、履约与新开票暂不可操作。<ElButton text type="primary" @click="r.push({path:'/aftersale',query:{order:order.id}})">查看售后</ElButton></div><div class="biz-tabs"><button v-for="[key,label] in panes" :key="key" class="biz-tab" :class="{active:tab===key}" @click="tab=key">{{label}}</button></div><section v-if="tab==='bill'" class="biz-section"><h2>订单账单</h2><div class="biz-pair"><span>服务</span><strong>{{order.serviceName}}</strong></div><div class="biz-pair"><span>订单金额</span><strong>{{money(order.amount)}}</strong></div><div class="biz-pair"><span>实付金额</span><strong>{{money(order.paid)}}</strong></div><div class="biz-pair"><span>已退款</span><strong>{{money(order.refunded)}}</strong></div><div class="biz-pair"><span>可开票金额</span><strong>{{money(c.invoiceable(order))}}</strong></div><div class="biz-actions" style="margin-top:20px"><ElButton @click="r.push({path:'/invoice/open',query:{order:order.id}})">对客开票</ElButton><ElButton @click="r.push({path:'/aftersale',query:{order:order.id}})">查看售后</ElButton></div></section><section v-else-if="tab==='contract'" class="biz-section"><h2>服务合同</h2><div class="biz-pair"><span>合同文件</span><strong>{{order.contractFile||'尚未上传'}}</strong></div><div class="biz-pair"><span>确认状态</span><strong>{{({none:'待上传',waiting:'等待客户确认',rejected:'客户已驳回，可重新上传',confirmed:'客户已确认'})[order.contractState]}}</strong></div><label v-if="order.status==='pending_contract'&&['none','rejected'].includes(order.contractState)&&!refund" class="biz-field" style="margin-top:20px">上传签署合同扫描件<input type="file" accept=".pdf,.png,.jpg,.jpeg,.doc,.docx" @change="pick($event,'contract')"/><small>上传后等待客户在园区客户端确认；供应商端不会代客户确认。</small></label><p v-if="order.status==='pending_payment'" class="biz-note">客户完成支付后，订单进入待签约才可上传合同。</p></section><section v-else-if="tab==='delivery'" class="biz-section"><h2>履约交付</h2><div class="biz-pair"><span>已提交文件</span><strong>{{order.deliverables.join('、')||'—'}}</strong></div><div class="biz-pair"><span>交付说明</span><strong>{{order.deliveryNote||'—'}}</strong></div><div class="biz-pair"><span>申请验收时间</span><strong>{{dateText(order.acceptanceAt)}}</strong></div><template v-if="order.status==='in_service'&&!refund"><label class="biz-field" style="margin-top:20px">交付文件 <b class="required">*</b><input type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.doc,.docx" @change="pick($event,'delivery')"/><small>{{files.join('、')}}</small></label><label class="biz-field" style="margin:15px 0">交付说明<ElInput v-model="note" type="textarea" :rows="3" maxlength="1000"/></label><ElButton type="primary" @click="deliver">提交客户验收</ElButton></template><p v-else-if="order.status==='pending_acceptance'" class="biz-note">等待客户验收；自本次申请起 7 个自然日未处理将自动通过。</p></section><section v-else-if="tab==='settlement'" class="biz-section"><h2>结算与评价</h2><div class="biz-pair"><span>结算状态</span><strong>{{order.settlement==='settled'?'已结算':'待结算'}}</strong></div><div class="biz-pair"><span>平台提点快照</span><strong>{{order.shareRate}}%</strong></div><div class="biz-pair"><span>售后期截止</span><strong>{{dateText(order.afterSaleEnd)}}</strong></div><div class="biz-actions" style="margin-top:20px"><ElButton @click="r.push({path:'/review',query:{order:order.id}})">查看评价</ElButton><ElButton @click="r.push({path:'/invoice/open',query:{order:order.id}})">申请开票</ElButton><ElButton @click="r.push('/wallet')">我的钱包</ElButton></div></section><section v-else class="biz-section"><h2>服务详情</h2><div class="biz-pair"><span>服务名称</span><strong>{{order.serviceName}}</strong></div><div class="biz-pair"><span>服务分类</span><strong>{{order.category}}</strong></div><ElButton @click="r.push('/service')">查看服务管理</ElButton></section></div><aside class="order-aside biz-card"><h3>订单信息</h3><div class="biz-pair"><span>来源园区</span><strong>{{c.joinedParks.find(p=>p.id===order?.parkId)?.name||'—'}}</strong></div><div class="biz-pair"><span>客户</span><strong>{{order.customer}}</strong></div><div class="biz-pair"><span>下单时间</span><strong>{{dateText(order.createdAt)}}</strong></div><h3>订单进度</h3><div class="timeline"><div v-for="s in ['pending_payment','pending_contract','in_service','pending_acceptance','completed']" :key="s" :class="{active:order.status===s}">{{STATUS_LABEL[s as keyof typeof STATUS_LABEL]}}</div><div v-if="order.status==='cancelled'" class="active">已取消</div></div></aside></div></div><div v-else class="biz-page biz-empty"><h3>订单不存在</h3><ElButton @click="r.push('/order')">返回订单管理</ElButton></div></template><style scoped>.order-layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:30px}.order-aside{padding:18px 20px;align-self:start}.order-aside h3{font-size:15px;margin:5px 0 13px}.order-aside .biz-pair{grid-template-columns:75px 1fr}.timeline{border-left:1px solid #d8e0ed;margin:20px 0 0 7px;padding-left:18px;display:grid;gap:18px;color:#8b97a7;font-size:13px}.timeline>div:before{content:'';position:absolute;width:8px;height:8px;border-radius:50%;background:#ccd5e4;margin-left:-23px;margin-top:5px}.timeline .active{color:#3156c5;font-weight:700}.timeline .active:before{background:#3156c5}@media(max-width:900px){.order-layout{grid-template-columns:1fr}}</style>
